export async function drain(queue: Queue, handler: (job: Job) => Promise<void>, maxAttempts = 2) {
  const completed: string[] = [];
  let job: Job | undefined;
  while ((job = queue.next())) {
    try { await handler(job); completed.push(job.id); }
    catch (error) {
      const attempts = (job.attempts ?? 0) + 1;
      if (attempts >= maxAttempts) throw new Error(`job ${job.id} failed after ${attempts} attempts`, { cause: error });
      queue.enqueue({ ...job, attempts });
    }
  }
  return completed;
